yaml_get_section_key() {
  local file="$1"
  local section="$2"
  local key="$3"

  awk -v section="$section" -v key="$key" '
    $0 ~ ("^" section ":[[:space:]]*$") {
      in_section = 1
      next
    }

    in_section && $0 ~ /^[^[:space:]]/ {
      in_section = 0
    }

    in_section && $0 ~ ("^[[:space:]]{2}" key ":[[:space:]]*") {
      value = $0
      sub("^[[:space:]]{2}" key ":[[:space:]]*", "", value)
      print value
      exit
    }
  ' "$file" | yaml_trim_scalar
}

