yaml_get_first_named_list_item() {
  local file="$1"
  local section="$2"

  awk -v section="$section" '
    function trim(value) {
      sub(/^[[:space:]]+/, "", value)
      sub(/[[:space:]]+$/, "", value)
      gsub(/^"/, "", value)
      gsub(/"$/, "", value)
      gsub(/^'"'"'/, "", value)
      gsub(/'"'"'$/, "", value)
      return value
    }

    $0 ~ ("^" section ":[[:space:]]*$") {
      in_section = 1
      next
    }

    in_section && $0 ~ /^[^[:space:]]/ {
      in_section = 0
    }

    in_section && $0 ~ /^[[:space:]]*-[[:space:]]+name:[[:space:]]*/ {
      value = $0
      sub(/^[[:space:]]*-[[:space:]]+name:[[:space:]]*/, "", value)
      print trim(value)
      exit
    }
  ' "$file"
}

require_selected_runtime() {
