		if len(choices) == 0 && v.Obj == nil {
			switch v.Name {
			case "string", "bool", "byte", "rune", "int", "int8", "int16", "int32", "int64", "uint", "uint8", "uint16", "uint32", "uint64", "uintptr", "float32", "float64", "complex64", "complex128":
				return true
			}
			return false
		}
