sourceBindings.exact:
credential_binding() {
  # Domain separation is essential: SHA256(salt/master key) alone is LiteLLM's
  # actual encryption key and must NEVER be placed in a backup manifest.
  printf 'kubeclaw-recovery-credential-binding.v1\0%s\0%s' "$LITELLM_MASTER_KEY" "${LITELLM_SALT_KEY-$LITELLM_MASTER_KEY}" | sha256sum | cut -d' ' -f1
}

client_version() {
  local value
  value=$("$1" --version)
  [[ $value =~ PostgreSQL\)\ ([0-9]+)\.([0-9]+) ]] || fail CLIENT_VERSION_INVALID
  printf '%s\n' "$(( 10#${BASH_REMATCH[1]} * 10000 + 10#${BASH_REMATCH[2]} ))"
}

metadata() {
  awk -F= -v key="$2" '$1==key {count++; value=substr($0,length(key)+2)} END {if(count!=1) exit 1; print value}' "$1/metadata.env"
}

migrate() {
  local directory=$1 source_version=$2
  positive SOURCE_VERSION "$source_version"
  (( source_version >= 100000 && source_version < BACKUP_EXPECTED_SERVER_VERSION )) || fail FORWARD_MIGRATION_REQUIRED
  restore "$directory" "$source_version"
}

